"""Cantor / diagonal obstruction: the diagonal set escapes any candidate map."""
from typing import Callable, Dict, FrozenSet, Sequence


def diagonal_missed_subset(A: Sequence[int],
                           f: Callable[[int], FrozenSet[int]]) -> FrozenSet[int]:
    """D = { a : a not in f(a) } is never in the image of f : A -> P(A)."""
    return frozenset(a for a in A if a not in f(a))


if __name__ == "__main__":
    A = list(range(5))
    attempt: Dict[int, FrozenSet[int]] = {
        0: frozenset(), 1: frozenset({0}), 2: frozenset({0, 1, 2}),
        3: frozenset({3, 4}), 4: frozenset({1, 4}),
    }
    f = lambda a: attempt[a]
    D = diagonal_missed_subset(A, f)
    image = {f(a) for a in A}
    print(f"diagonal set D = {set(D)}")
    print(f"D in image(f)? {D in image}  (False: no surjection A -> P(A))")
    print(f"|A| = {len(A)}, |P(A)| = {2 ** len(A)}")

"""Knaster-Tarski least fixed point via Kleene iteration from the bottom."""
from typing import Callable, FrozenSet, Sequence


def least_fixed_point(ground: Sequence[int],
                      f: Callable[[FrozenSet[int]], FrozenSet[int]]) -> FrozenSet[int]:
    current: FrozenSet[int] = frozenset()
    while True:
        nxt = f(current)
        if nxt == current:
            return current
        current = nxt


if __name__ == "__main__":
    edges = {0: {2}, 2: {4}, 1: {3}, 3: {1}}

    def f(S: FrozenSet[int]) -> FrozenSet[int]:
        out = set(S) | {0}
        for x in list(S):
            out |= edges.get(x, set())
        return frozenset(out)

    lfp = least_fixed_point(list(range(5)), f)
    print(f"lfp(f) = {sorted(lfp)}, is fixed point: {f(lfp) == lfp}")

