function LAWVERE_DIAGONAL(states, base_diag, g, s, a0):
    require g(s) == s                      # s is a fixed point of g
    for a in states:
        if a == a0: twisted[a] <- s
        else:       twisted[a] <- g(base_diag[a])
    # twisted == phi, the row f(a0); its diagonal entry is g-invariant
    assert twisted[a0] == g(twisted[a0])
    return (a0, twisted[a0])              # strange-loop state and value

function SELF_MODELING_DEFICITS(max_states, values):
    require values >= 2
    result <- []
    for n in 1 .. max_states:
        result.append( (n, values^n - n) )  # strictly positive
    return result

function YONEDA_INVARIANT(objects, hom):
    for X in objects:
        profile <- []
        for Z in objects:
            profile.append( (Z, |hom[Z, X]|) )
        result[X] <- sort(profile)
    return result

