"""Visualize Kleene iteration converging to the Knaster-Tarski least fixed point."""
import matplotlib.pyplot as plt

edges = {0: {2}, 2: {4}, 1: {3}, 3: {1}}


def f(S):
    out = set(S) | {0}
    for x in list(S):
        out |= edges.get(x, set())
    return frozenset(out)


chain, current = [], frozenset()
for _ in range(8):
    chain.append(len(current))
    nxt = f(current)
    if nxt == current:
        break
    current = nxt

plt.step(range(len(chain)), chain, where="post", marker="o")
plt.xlabel("iteration k")
plt.ylabel("|f^k(bottom)|")
plt.title("Kleene ascent to the least fixed point lfp(f) = sup f^k(bottom)")
plt.grid(True, alpha=0.3)
plt.tight_layout()
plt.savefig("tarski_ascent.png", dpi=150)
